const cmds = [
  ["inbox-overview", "\"$HORIZON_BIN\" inbox list --mine --status open --json 2>/dev/null | jq '{attention,warnings,total:(.items|length),by_kind:(.items|group_by(.kind)|map({kind:.[0].kind,count:length}))}'"],
  ["conversations", "\"$HORIZON_BIN\" inbox list --mine --status open --kind conversation --json 2>/dev/null | jq '[.items[] | {id,kind,status,body,audience,owner_task,project,labels,created_at,updated_at,metadata,comments:(.comments|map({id,author,at,body,provenance}))}]'"],
  ["memories", "\"$HORIZON_BIN\" inbox list --mine --status open --kind memory --json 2>/dev/null | jq '[.items[] | {id,kind,status,body,audience,owner_task,project,labels,created_at,updated_at,metadata,comments:(.comments|map({id,author,at,body,provenance}))}]'"],
  ["nonprotections", "\"$HORIZON_BIN\" inbox list --mine --status open --json 2>/dev/null | jq '[.items[] | select(.kind!=\"protection\") | {id,kind,status,body:(.body|split(\"\\n\")|.[0]),audience,owner_task,project,labels,created_at,updated_at,metadata,comment_count:(.comments|length)}]'"]
];
const rs=await Promise.all(cmds.map(async([name,cmd])=>{
 const r=await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:30000,max_output_tokens:50000});
 return `--- ${name} ---\n${r.output}`;
}));
rs.forEach(text);

