root="/home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/inbox/local/items"
Dir["#{root}/*.yaml"].sort.each do |f|
 x=YAML.load_file(f); next unless x["status"]=="open" && x["kind"]=="memory"; puts "--- #{x["id"]} ---"; puts x["body"]; puts "metadata=#{x["metadata"].inspect}"; puts "comments=#{(x["comments"]||[]).map{|c| c["body"]}.inspect}"; end
'","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon","yield_time_ms":30000,"max_output_tokens":40000});
text(r.output);

